"""Render the orientation-specific summary as a standalone interactive chart."""
import argparse
import json
from pathlib import Path
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('results', type=Path)
p = parser.parse_args().results
data = json.loads((p/'summary.json').read_text())
html = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Coordinated WAL comparison</title><style>
:root{font-family:var(--font-sans,system-ui);color:var(--foreground,inherit)}body{margin:0}*{box-sizing:border-box}p{line-height:1.5;margin:10px 0}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:8px 0 18px}label{display:grid;gap:5px;flex:1;min-width:200px;font-size:13px}select{font:inherit;color:var(--foreground);background:var(--card);border:1px solid var(--border,currentColor);border-radius:var(--radius,8px);padding:9px}.small{font-size:12px;color:var(--muted-foreground,inherit)}.chart{height:260px;display:grid;gap:6px}.row{display:grid;grid-template-columns:84px minmax(70px,1fr) 88px;align-items:center;gap:8px;font-size:13px}.track{height:28px;position:relative}.range{position:absolute;top:12px;height:5px;background:var(--tone);opacity:.4;min-width:2px}.point{position:absolute;top:7px;width:15px;height:15px;background:var(--tone);border:2px solid var(--foreground,currentColor);border-radius:50%;transform:translateX(-50%)}.number{text-align:right;font-variant-numeric:tabular-nums}.legend{margin:12px 0}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px;font-variant-numeric:tabular-nums}th,td{text-align:right;padding:8px 5px;border-bottom:1px solid var(--border,currentColor)}th:first-child,td:first-child{text-align:left}caption{text-align:left;line-height:1.5;font-weight:600;padding:8px 0}.scope{border-left:3px solid var(--border,currentColor);padding-left:12px;margin-top:18px}a{color:var(--primary,inherit)}
</style><body><p><strong>__PAIRS__ coordinated WAL reader/writer pairs</strong> · 5 callers · __ATTEMPTS__ writer attempts × __ROWS__ rows · 5 pairs per orientation</p><p class="small">Clean source __SOURCE__ · common SQLite 3.54.1 · shared host · no production code change</p><div class="controls"><label>CPU orientation<select id="orientation"><option value="6">Writer6 / reader7</option><option value="7">Writer7 / reader6</option></select></label><label>Measured quantity<select id="metric"><option value="reader-p50">Checked reader p50 (µs)</option><option value="reader-p99">Checked reader p99 (µs)</option><option value="writer-p50">Successful commit p50 (µs)</option><option value="writer-p99">Successful commit p99 (µs)</option><option value="writer-rate">Recorded writer commits/s</option><option value="reader-rate">COORDINATED snapshots/s</option><option value="reader-rss">Reader lifetime peak RSS (KiB)</option><option value="writer-rss">Writer lifetime peak RSS (KiB)</option></select></label></div><div id="chart" class="chart" role="img" aria-label="Five caller medians and observed ranges"></div><p id="interpretation" class="small legend"></p><div class="scroll"><table><caption id="caption"></caption><thead><tr><th>Caller</th><th>Median</th><th>Min–max</th><th>Reader snapshots</th></tr></thead><tbody id="table"></tbody></table></div><div class="scope"><p class="small">Dots are medians of five pair summaries; lines are observed min–max, not confidence intervals. Latency quantiles are computed within each role, never pooled. Reader work counts and cadence vary: pairs do not offer identical reader load. SQL operation clocks include copying and full payload checks; role rates include logging, with parent waits additionally included for reader rates.</p><p class="small">One WAL writer; __COUNTS__. All pairs passed intermediate epoch bands, strict snapshots, independent final data/integrity and clean exits. Separate lifetime RSS peaks include payload precomputation and must not be summed. Files are warm/compressible on Btrfs; existing compiler jobs were observed during builds before the measured-pair window; measured overlap is unproven. No isolated speedup, checkpoint-cause, saturation or power-loss claim.</p></div><script>
const DATA=__DATA__;
const names={'goose':'Goose','raw-c-api':'Raw C API','sqlitecpp':'SQLiteCpp','rusqlite':'rusqlite','python':'Python'};
const cpus=[...new Set(DATA.rows.map(r=>r.writer_cpu))];document.querySelector('#orientation').innerHTML=cpus.map(c=>`<option value="${c}">Writer${c} / reader${cpus.find(x=>x!==c)}</option>`).join('');
const callers=Object.keys(names),fmt=x=>x.toLocaleString('en',{maximumFractionDigits:2});
function draw(){const cpu=Number(document.querySelector('#orientation').value),metric=document.querySelector('#metric').value,[role,kind]=metric.split('-');const rows=callers.map(c=>{const r=DATA.rows.find(x=>x.writer_cpu===cpu&&x.implementation===c&&x.role===role);let s=kind==='rate'?r.successful_operations_per_second:kind==='rss'?r.role_peak_rss_kib:r.successful_latency.quantiles[kind];const scale=['p50','p99'].includes(kind)?1000:1;return{r,s:Object.fromEntries(Object.entries(s).map(([k,v])=>[k,v/scale]))}});const max=Math.max(...rows.map(x=>x.s.maximum))*1.08;document.querySelector('#chart').innerHTML=rows.map(({r,s},i)=>`<div class="row" style="--tone:var(--chart-${i+1},var(--primary,#666))"><span>${names[r.implementation]}</span><div class="track"><span class="range" style="left:${s.minimum/max*100}%;width:${(s.maximum-s.minimum)/max*100}%"></span><span class="point" style="left:${s.median/max*100}%"></span></div><span class="number">${fmt(s.median)}</span></div>`).join('');const title=document.querySelector('#metric').selectedOptions[0].textContent;document.querySelector('#caption').textContent=title+' · writer CPU'+cpu;document.querySelector('#table').innerHTML=rows.map(({r,s})=>{const reader=DATA.rows.find(x=>x.writer_cpu===cpu&&x.implementation===r.implementation&&x.role==='reader');return`<tr><td>${names[r.implementation]}</td><td>${fmt(s.median)}</td><td>${fmt(s.minimum)}–${fmt(s.maximum)}</td><td>${reader.successes_per_pair.minimum}–${reader.successes_per_pair.maximum}/pair</td></tr>`}).join('');document.querySelector('#interpretation').textContent=kind==='rate'?(role==='reader'?'Higher records more snapshots per second in this coordinated workload, including variable IPC cadence.':'Higher records more commits per second in the coupled writer loop, including event logging.'):(kind==='rss'?'Lower records a smaller separate whole-lifetime process peak, not incremental binding heap.':'Lower records less checked operation time in this workload. Tail spreads include shared-host effects.');}
document.querySelectorAll('select').forEach(x=>x.addEventListener('change',draw));draw();
</script></body></html>'''.replace('__DATA__',json.dumps(data,separators=(',',':')).replace('</','<\\/'))
html = html.replace('__PAIRS__', str(data['pair_count'])).replace('__ATTEMPTS__', str(data['attempts'])).replace('__ROWS__', str(data['row_count'])).replace('__SOURCE__', data['source_commit'][:7])
commits = sum(r['success_count'] for r in data['rows'] if r['role'] == 'writer')
busy = sum(r['busy_count'] for r in data['rows'])
html = html.replace('__COUNTS__', f'{commits:,} successful commits and {busy:,} BEGIN-BUSY results were observed')
(p/'report.html').write_text(html)
